import type {
  NextFunction,
  Request,
  RequestHandler,
  Response,
} from "express";
import { Redis } from "ioredis";
import { RateLimiterRedis } from "rate-limiter-flexible";
import { logger } from "@eventflow/common";

const configuredPoints = Number(process.env.RATE_LIMIT_POINTS ?? 100);
const configuredDurationSeconds = Number(
  process.env.RATE_LIMIT_DURATION_SECONDS ?? 60,
);
const points =
  Number.isFinite(configuredPoints) && configuredPoints > 0
    ? configuredPoints
    : 100;
const durationSeconds =
  Number.isFinite(configuredDurationSeconds) && configuredDurationSeconds > 0
    ? configuredDurationSeconds
    : 60;
const redisUrl = process.env.REDIS_URL;

const redisClient = redisUrl
  ? new Redis(redisUrl, {
      enableOfflineQueue: false,
      maxRetriesPerRequest: 1,
      lazyConnect: true,
    })
  : null;

const rateLimiter = redisClient
  ? new RateLimiterRedis({
      storeClient: redisClient,
      keyPrefix: "eventflow:rate-limit",
      points,
      duration: durationSeconds,
    })
  : null;

let missingRedisWarningLogged = false;

export const rateLimiterMiddleware: RequestHandler = async (
  request: Request,
  response: Response,
  next: NextFunction,
): Promise<void> => {
  if (!rateLimiter) {
    if (!missingRedisWarningLogged) {
      missingRedisWarningLogged = true;
      logger.warn(
        "REDIS_URL no está configurada; rate limiting deshabilitado (fail-open)",
      );
    }
    next();
    return;
  }

  const clientIp = getClientIp(request);

  try {
    const result = await rateLimiter.consume(clientIp);
    response.setHeader("X-RateLimit-Limit", String(points));
    response.setHeader(
      "X-RateLimit-Remaining",
      String(result.remainingPoints),
    );
    next();
  } catch (error: unknown) {
    if (isRateLimitExceeded(error)) {
      const retryAfterSeconds = Math.max(
        1,
        Math.ceil(error.msBeforeNext / 1000),
      );
      response.setHeader("Retry-After", String(retryAfterSeconds));
      response.setHeader("X-RateLimit-Limit", String(points));
      response.setHeader("X-RateLimit-Remaining", "0");
      response.status(429).json({
        success: false,
        error: {
          code: "RATE_LIMIT_EXCEEDED",
          message: "Demasiadas peticiones. Inténtalo de nuevo más tarde.",
          retryAfterSeconds,
        },
      });
      return;
    }

    logger.error(
      { error, clientIp },
      "Redis no disponible para rate limiting; se permite la petición (fail-open)",
    );
    next();
  }
};

export const rateLimitMiddleware = rateLimiterMiddleware;

export async function closeRateLimiter(): Promise<void> {
  if (redisClient) {
    await redisClient.quit();
  }
}

function getClientIp(request: Request): string {
  const forwardedFor = request.header("x-forwarded-for");
  if (forwardedFor) {
    const firstIp = forwardedFor.split(",")[0]?.trim();
    if (firstIp) return firstIp;
  }
  return request.ip || request.socket.remoteAddress || "unknown";
}

function isRateLimitExceeded(
  error: unknown,
): error is { msBeforeNext: number; remainingPoints?: number } {
  return (
    typeof error === "object" &&
    error !== null &&
    "msBeforeNext" in error &&
    typeof error.msBeforeNext === "number" &&
    Number.isFinite(error.msBeforeNext)
  );
}
